using System;using System.Drawing;using System.Linq;using System.Reflection;using System.Threading;using System.Windows.Forms;
namespace Frociart.Tests {static class LessonInteractionTests {
 static int checks;static BindingFlags F=BindingFlags.Instance|BindingFlags.NonPublic|BindingFlags.Public;static void Check(bool b,string t){if(!b)throw new Exception(t);checks++;Console.WriteLine("PASS "+t);}static T Get<T>(object o,string name){return(T)o.GetType().GetField(name,F).GetValue(o);}static object Call(object o,string n,params object[] a){return o.GetType().GetMethods(F).First(m=>m.Name==n&&m.GetParameters().Length==a.Length).Invoke(o,a);}static void Pump(int ms=40){var end=DateTime.UtcNow.AddMilliseconds(ms);do{Application.DoEvents();Thread.Sleep(2);}while(DateTime.UtcNow<end);}static void Mouse(FlowCanvas c,string method,Point p){typeof(FlowCanvas).GetMethod(method,F).Invoke(c,new object[]{new MouseEventArgs(MouseButtons.Left,1,p.X,p.Y,0)});}
 [STAThread]static int Main(){try{Application.EnableVisualStyles();UiMotion.SetEnabled(true);Ui.SetDarkMode(true,false);using(var d=new TutorDialog(new TutorStore(),new LearningStore())){d.ShowInTaskbar=false;d.StartPosition=FormStartPosition.Manual;d.Location=new Point(-4000,-3000);d.Show();Pump(380);
 foreach(var lesson in Tutor.Lessons){d.SelectLesson(lesson.id);Pump(340);var page=Get<Panel>(d,"page");var intro=page.Controls.Cast<Control>().SelectMany(x=>All(x)).OfType<TutorTabs>().First();for(int tab=0;tab<intro.TabCount;tab++){intro.SelectedIndex=tab;Pump(330);Check(!intro.TabPages[tab].UseVisualStyleBackColor&&intro.TabPages[tab].BackColor==Ui.Surface,"Lesson tab has themed opaque background: "+lesson.id+"/"+tab);}Get<FlowButton>(d,"primary").PerformClick();Pump(330);Call(d,"ReleasePage");d.Current.Drafts.Clear();d.Current.Document=lesson.Solution();d.Current.Step=0;Call(d,"RenderWorkspace");Pump(330);var n=d.Current.Document.Nodes.FirstOrDefault(x=>x.Kind!=NodeKind.Start&&x.Kind!=NodeKind.End);if(n==null){var terminalTabs=Get<TabControl>(d,"inspectorTabs");terminalTabs.SelectedIndex=1;Call(d,"StepRunner");Check(Get<Interpreter>(d,"runner").Steps>0,"Terminal-only introductory lesson runs: "+lesson.id);terminalTabs.SelectedIndex=0;continue;}d.Canvas.SelectNode(n.Id);Pump(340);var box=Get<TextBox>(d,"expression");Check(box!=null,"Selected lesson block exposes editor: "+lesson.id);box.Focus();box.Text+=" ";string text=TutorTextDialog.Source(box.Text);var tabs=Get<TabControl>(d,"inspectorTabs");tabs.SelectedIndex=1;Pump(340);Check(d.Canvas.ViewOnly,"Lesson trial enters read-only mode: "+lesson.id);Call(d,"StepRunner");Pump(80);Check(Get<Interpreter>(d,"runner")!=null&&Get<Interpreter>(d,"runner").Steps>0,"Native Un passo advances: "+lesson.id);Check(n.Text==text,"Prova applies the current typed edit: "+lesson.id);var b=FlowCanvas.GetNodeBounds(n);var point=Point.Round(d.Canvas.WorldToClient(new PointF(b.X+b.Width/2,b.Y+b.Height/2)));Mouse(d.Canvas,"OnMouseDown",point);Mouse(d.Canvas,"OnMouseUp",point);Pump(340);Check(tabs.SelectedIndex==0&&!d.Canvas.ViewOnly&&d.Canvas.SelectedNodeId==n.Id,"Clicking trial block returns to that block editor: "+lesson.id);var current=Get<TextBox>(d,"expression");Check(current!=null&&TutorTextDialog.Source(current.Text)==text,"Returning editor retains exact content: "+lesson.id);Call(d,"UpdateTask");Pump(80);Check(d.Canvas.SelectedNodeId==n.Id,"Task update does not override selection: "+lesson.id);
 }
 d.ShowOverview();Pump(350);Check(FlowTransitions.Active==0&&PopupGhost.ActiveCount==0,"Overview finishes all page transitions");d.Close();Pump(350);}
 using(var f=new Form{ShowInTaskbar=false,Location=new Point(-4000,-3000),StartPosition=FormStartPosition.Manual,Size=new Size(500,400)}){var panel=new Panel{Dock=DockStyle.Fill,BackColor=Ui.Surface};panel.Controls.Add(new Label{Text="Before",BackColor=Ui.Surface});f.Controls.Add(panel);f.Show();Pump(40);FlowTransitions.Change(panel);Check(FlowTransitions.Active>0&&PopupGhost.ActiveCount>0,"Previous page surface exists before its controls are removed");panel.Controls.Clear();panel.Controls.Add(new Label{Text="After",BackColor=Ui.Surface});Pump(80);Check(PopupGhost.ActiveCount>0,"Previous page fades through intermediate frames after the replacement paints");Pump(350);Check(FlowTransitions.Active==0&&PopupGhost.ActiveCount==0,"Page crossfade cleans its native surface");FlowTransitions.Change(panel);panel.Dispose();Pump(30);Check(FlowTransitions.Active==0&&PopupGhost.ActiveCount==0,"Disposal during page change cannot leave a stale overlay");f.Close();}
 Console.WriteLine("LESSON_INTERACTION_FINISHED checks="+checks+" lessons=24 errors=0");return 0;}catch(Exception e){Console.WriteLine(e);return 1;}}
 static System.Collections.Generic.IEnumerable<Control> All(Control c){yield return c;foreach(Control v in c.Controls)foreach(var x in All(v))yield return x;}
 }}
